ALTER TABLE public.client_tasks ADD COLUMN blocked_since timestamptz, ADD COLUMN blocker_reason text, ADD COLUMN blocker_impact text;
ALTER TABLE public.recurring_tasks ADD COLUMN blocked_since timestamptz, ADD COLUMN blocker_reason text, ADD COLUMN blocker_impact text, ADD COLUMN escalation_level integer NOT NULL DEFAULT 0, ADD COLUMN last_escalated_at timestamptz;
ALTER TABLE public.recurring_tasks DROP CONSTRAINT recurring_tasks_status_check;
ALTER TABLE public.recurring_tasks ADD CONSTRAINT recurring_tasks_status_check CHECK(status IN('not_started','in_progress','blocked','waiting_client','done','missed_review','closed','superseded'));
ALTER TABLE public.client_message_outbox ADD COLUMN cc_addresses text[] NOT NULL DEFAULT '{}', ADD COLUMN blocker_id uuid, ADD COLUMN activation_request_id uuid;
ALTER TABLE public.pipeline_activation_requests ADD COLUMN assigned_to uuid REFERENCES public.profiles(id), ADD COLUMN follow_up_due date, ADD COLUMN scope_notes text, ADD COLUMN scope_confirmed_at timestamptz, ADD COLUMN onboarding_completed_at timestamptz, ADD COLUMN tasks_assigned_at timestamptz;
CREATE TABLE public.task_approval_blockers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_kind text NOT NULL CHECK(task_kind IN('launch','recurring')),task_id uuid NOT NULL,client_id uuid NOT NULL REFERENCES public.clients(id),pipeline_id uuid REFERENCES public.pipelines(id),task_name text NOT NULL,reason text NOT NULL DEFAULT 'Waiting on client approval',impact text NOT NULL,blocked_since timestamptz NOT NULL,first_reminder_at timestamptz,last_reminder_at timestamptz,owner_approved_at timestamptz,resolved_at timestamptz,resolved_by uuid REFERENCES public.profiles(id),resolution_note text,UNIQUE(task_kind,task_id,blocked_since));
GRANT SELECT ON public.task_approval_blockers TO authenticated; GRANT ALL ON public.task_approval_blockers TO service_role; ALTER TABLE public.task_approval_blockers ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.scorecard_can_view(_person uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (is_staff(auth.uid()) OR has_role(auth.uid(),'hr')) AND (is_staff(_person) OR has_role(_person,'hr') OR has_role(_person,'finance')) AND (auth.uid()=_person OR is_manager(auth.uid()) OR has_role(auth.uid(),'bd_manager') OR has_role(auth.uid(),'hr') OR EXISTS(SELECT 1 FROM pipeline_members h JOIN pipeline_members m ON m.pipeline_id=h.pipeline_id WHERE h.user_id=auth.uid() AND h.role='head' AND h.active AND m.active AND m.user_id=_person)) $$;
REVOKE ALL ON FUNCTION public.scorecard_can_view(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.scorecard_can_view(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.blocker_can_manage(_client uuid,_pipeline uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (is_manager(auth.uid()) OR has_role(auth.uid(),'bd_manager') OR (is_pipeline_head(auth.uid(),_pipeline) AND EXISTS(SELECT 1 FROM client_staff_assignments WHERE client_id=_client AND pipeline_id=_pipeline AND user_id=auth.uid() AND NOT excluded))) $$;
REVOKE ALL ON FUNCTION public.blocker_can_manage(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.blocker_can_manage(uuid,uuid) TO authenticated,service_role;
CREATE POLICY blockers_read ON public.task_approval_blockers FOR SELECT TO authenticated USING(blocker_can_manage(client_id,pipeline_id) OR (has_role(auth.uid(),'client') AND EXISTS(SELECT 1 FROM clients c WHERE c.id=client_id AND my_client_id() IN(c.id,c.parent_client_id))));
CREATE OR REPLACE FUNCTION public.working_days_after(_start date,_end date) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*)::int FROM generate_series(_start+1,_end,interval '1 day') d WHERE extract(isodow FROM d)<>7 AND NOT EXISTS(SELECT 1 FROM activity_holidays WHERE day=d::date) $$;
CREATE OR REPLACE FUNCTION public.working_day_after(_date date) RETURNS date LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d date:=_date+1; BEGIN WHILE extract(isodow FROM d)=7 OR EXISTS(SELECT 1 FROM activity_holidays WHERE day=d) LOOP d:=d+1; END LOOP; RETURN d; END $$;
CREATE OR REPLACE FUNCTION public.blocked_escalation_level(_since timestamptz,_at timestamptz) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN _at-_since>=interval '144 hours' THEN 3 WHEN _at-_since>=interval '96 hours' THEN 2 WHEN _at-_since>=interval '48 hours' THEN 1 ELSE 0 END $$;
REVOKE ALL ON FUNCTION public.working_days_after(date,date),public.working_day_after(date),public.blocked_escalation_level(timestamptz,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.working_days_after(date,date),public.working_day_after(date),public.blocked_escalation_level(timestamptz,timestamptz) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pipeline_default_backup(_pipeline uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT pm.user_id FROM pipeline_members pm JOIN profiles p ON p.id=pm.user_id AND p.status='active' WHERE pm.pipeline_id=_pipeline AND pm.role='head' AND pm.active ORDER BY pm.created_at,pm.user_id LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.pipeline_default_backup(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pipeline_default_backup(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.task_blocker_track() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid;pid uuid;nm text;kind text; active_block boolean; BEGIN
kind:=CASE WHEN TG_TABLE_NAME='client_tasks' THEN 'launch' ELSE 'recurring' END;
IF kind='launch' THEN cid:=NEW.client_id; SELECT id INTO pid FROM pipelines WHERE code=NEW.pipeline_code; nm:=NEW.name; ELSE SELECT cp.client_id,cp.pipeline_id,i.name||' · '||NEW.stage INTO cid,pid,nm FROM activity_plans p JOIN client_pipelines cp ON cp.id=p.client_pipeline_id JOIN activity_items i ON i.id=NEW.item_id WHERE p.id=NEW.plan_id; END IF;
active_block:=NEW.status IN('blocked','waiting_client');
IF TG_OP='INSERT' THEN IF NEW.backup_id IS NULL AND pid IS NOT NULL THEN NEW.backup_id:=pipeline_default_backup(pid); END IF; IF active_block THEN NEW.blocked_since:=now(); END IF;
ELSE
 IF NEW.blocked_since IS DISTINCT FROM OLD.blocked_since AND auth.uid() IS NOT NULL AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Blocker timing is managed by the system'; END IF;
 IF active_block AND OLD.status NOT IN('blocked','waiting_client') THEN NEW.blocked_since:=now(); NEW.escalation_level:=0; NEW.last_escalated_at:=NULL; ELSIF NOT active_block THEN NEW.blocked_since:=NULL; END IF;
END IF;
IF NEW.status='waiting_client' THEN NEW.blocker_reason:='Waiting on client approval'; END IF;
IF active_block AND coalesce(btrim(NEW.blocker_reason),'')='' THEN NEW.blocker_reason:='Other blocker'; END IF;
IF active_block AND NEW.blocked_since IS NULL THEN NEW.blocked_since:=now(); END IF;
IF active_block AND NEW.blocker_reason='Waiting on client approval' THEN
 IF kind='launch' AND NOT NEW.requires_client_approval THEN RAISE EXCEPTION 'This task does not require client approval'; END IF;
 IF kind='recurring' AND NEW.stage<>'approval' THEN RAISE EXCEPTION 'Only the approval stage may wait for client approval'; END IF;
 IF coalesce(btrim(NEW.blocker_impact),'')='' THEN NEW.blocker_impact:='Progress on '||nm||' is paused until the required approval is received.'; END IF;
 INSERT INTO task_approval_blockers(task_kind,task_id,client_id,pipeline_id,task_name,impact,blocked_since) VALUES(kind,NEW.id,cid,pid,nm,NEW.blocker_impact,NEW.blocked_since) ON CONFLICT(task_kind,task_id,blocked_since) DO UPDATE SET impact=excluded.impact;
END IF;
IF kind='launch' AND NEW.client_approved_at IS NOT NULL THEN UPDATE task_approval_blockers SET owner_approved_at=coalesce(owner_approved_at,NEW.client_approved_at) WHERE task_kind=kind AND task_id=NEW.id AND resolved_at IS NULL; END IF;
RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.task_blocker_track() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_task_blocker_track BEFORE INSERT OR UPDATE ON public.client_tasks FOR EACH ROW EXECUTE FUNCTION public.task_blocker_track();
CREATE TRIGGER zz_recurring_blocker_track BEFORE INSERT OR UPDATE ON public.recurring_tasks FOR EACH ROW EXECUTE FUNCTION public.task_blocker_track();
CREATE OR REPLACE FUNCTION public.escalate_blocked_tasks(_at timestamptz DEFAULT now()) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;lvl int;k int;u uuid;n int:=0; BEGIN
FOR r IN SELECT 'launch' kind,t.id,t.client_id,p.id pipeline_id,t.name,t.blocked_since,t.escalation_level,'/launches/'||t.launch_id link FROM client_tasks t JOIN clients c ON c.id=t.client_id LEFT JOIN pipelines p ON p.code=t.pipeline_code JOIN client_launches l ON l.id=t.launch_id WHERE t.status IN('blocked','waiting_client') AND t.blocked_since IS NOT NULL AND l.status IN('active','live','offboarding') AND NOT c.is_test AND NOT c.is_demo
UNION ALL SELECT 'recurring',t.id,cp.client_id,cp.pipeline_id,i.name||' · '||t.stage,t.blocked_since,t.escalation_level,'/my-tasks' FROM recurring_tasks t JOIN activity_plans ap ON ap.id=t.plan_id JOIN activity_items i ON i.id=t.item_id JOIN client_pipelines cp ON cp.id=ap.client_pipeline_id JOIN clients c ON c.id=cp.client_id WHERE t.status IN('blocked','waiting_client') AND t.blocked_since IS NOT NULL AND NOT client_on_hold(cp.client_id) AND NOT c.is_test AND NOT c.is_demo LOOP
 lvl:=blocked_escalation_level(r.blocked_since,_at); FOR k IN r.escalation_level+1..lvl LOOP
 u:=NULL; IF k=1 THEN u:=pipeline_default_backup(r.pipeline_id); ELSIF k=2 THEN SELECT id INTO u FROM profiles WHERE email='shalini@alcorgetaways.com' AND status='active'; ELSE SELECT p.id INTO u FROM profiles p WHERE lower(p.email) IN('mohnish@group2001.in','alcorgetaways@gmail.com') AND has_role(p.id,'admin') AND p.status='active' ORDER BY CASE WHEN lower(p.email)='mohnish@group2001.in' THEN 0 ELSE 1 END LIMIT 1; END IF;
 IF u IS NOT NULL THEN INSERT INTO notifications(user_id,title,body,link,kind) VALUES(u,'Blocked task · escalation '||k,r.name||CASE k WHEN 1 THEN ': review the blocker and arrange a solution.' WHEN 2 THEN ': coordinate with the team and client.' ELSE ': management action needed.' END,r.link,'blocked_escalation'); END IF;
 END LOOP; IF lvl>r.escalation_level THEN IF r.kind='launch' THEN UPDATE client_tasks SET escalation_level=lvl,last_escalated_at=_at WHERE id=r.id; ELSE UPDATE recurring_tasks SET escalation_level=lvl,last_escalated_at=_at WHERE id=r.id; END IF;n:=n+1; END IF;
END LOOP;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.escalate_blocked_tasks(timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.escalate_blocked_tasks(timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.queue_blocker_reminders(_at timestamptz DEFAULT now()) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b task_approval_blockers;em text;cc text[];n int:=0;BEGIN
SELECT coalesce(array_agg(email),'{}') INTO cc FROM profiles WHERE email IS NOT NULL AND (email='shalini@alcorgetaways.com' OR (has_role(id,'admin') AND lower(email) IN('mohnish@group2001.in','alcorgetaways@gmail.com')));
FOR b IN SELECT x.* FROM task_approval_blockers x JOIN clients c ON c.id=x.client_id WHERE x.resolved_at IS NULL AND NOT client_on_hold(x.client_id) AND NOT c.is_test AND NOT c.is_demo AND working_days_after((x.blocked_since AT TIME ZONE 'Asia/Kolkata')::date,(_at AT TIME ZONE 'Asia/Kolkata')::date)>5 AND (x.last_reminder_at IS NULL OR _at>=x.last_reminder_at+interval '7 days') FOR UPDATE OF x LOOP
SELECT p.email INTO em FROM profiles p JOIN clients c ON c.id=b.client_id WHERE p.client_id IN(c.id,c.parent_client_id) AND p.status='active' AND has_role(p.id,'client') AND p.email IS NOT NULL ORDER BY CASE WHEN p.client_id=c.id THEN 0 ELSE 1 END LIMIT 1;
IF em IS NOT NULL THEN INSERT INTO client_message_outbox(client_id,channel,to_address,cc_addresses,kind,subject,body,task_id,blocker_id,held,created_at) VALUES(b.client_id,'email',em,cc,'approval_blocker_reminder','Pending approval: '||b.task_name,'Approval pending: '||b.task_name||'. Client-side issue: '||b.reason||'. Impact: '||b.impact||' Please review Pending approvals in North Star. After approval, the Pipeline Head or BD will confirm that the issue is resolved.',CASE WHEN b.task_kind='launch' THEN b.task_id END,b.id,true,_at); END IF;
UPDATE task_approval_blockers SET first_reminder_at=coalesce(first_reminder_at,_at),last_reminder_at=_at WHERE id=b.id;n:=n+1;
END LOOP; RETURN n;END $$;
REVOKE ALL ON FUNCTION public.queue_blocker_reminders(timestamptz) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.queue_blocker_reminders(timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.resolve_approval_blocker(_id uuid,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b task_approval_blockers;BEGIN PERFORM activity_require_ready();SELECT * INTO b FROM task_approval_blockers WHERE id=_id FOR UPDATE;IF b.id IS NULL OR NOT blocker_can_manage(b.client_id,b.pipeline_id) THEN RAISE EXCEPTION 'Pipeline Head, BD or Admin/Management only';END IF;IF b.owner_approved_at IS NULL THEN RAISE EXCEPTION 'The client must approve the item first';END IF;IF coalesce(btrim(_note),'')='' THEN RAISE EXCEPTION 'Enter how the approval issue was resolved';END IF;UPDATE task_approval_blockers SET resolved_at=now(),resolved_by=auth.uid(),resolution_note=btrim(_note) WHERE id=_id; UPDATE client_message_outbox SET held=true,failed_at=now(),error='Approval issue resolved; reminder cancelled' WHERE blocker_id=_id AND sent_at IS NULL AND failed_at IS NULL;END $$;
CREATE OR REPLACE FUNCTION public.approve_recurring_blocker(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b task_approval_blockers;BEGIN PERFORM activity_require_ready();SELECT * INTO b FROM task_approval_blockers WHERE id=_id FOR UPDATE;IF b.id IS NULL OR b.task_kind<>'recurring' OR NOT has_role(auth.uid(),'client') OR NOT EXISTS(SELECT 1 FROM clients c WHERE c.id=b.client_id AND my_client_id() IN(c.id,c.parent_client_id)) THEN RAISE EXCEPTION 'Only this hotel owner can approve';END IF;UPDATE task_approval_blockers SET owner_approved_at=coalesce(owner_approved_at,now()) WHERE id=_id;END $$;
REVOKE ALL ON FUNCTION public.resolve_approval_blocker(uuid,text),public.approve_recurring_blocker(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resolve_approval_blocker(uuid,text),public.approve_recurring_blocker(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.blocked_workspace() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM activity_require_ready();RETURN jsonb_build_object('blockers',coalesce((SELECT jsonb_agg(to_jsonb(b)) FROM task_approval_blockers b WHERE b.resolved_at IS NULL AND ((has_role(auth.uid(),'client') AND b.first_reminder_at IS NOT NULL AND EXISTS(SELECT 1 FROM clients c WHERE c.id=b.client_id AND my_client_id() IN(c.id,c.parent_client_id))) OR blocker_can_manage(b.client_id,b.pipeline_id))),'[]'),'tasks',CASE WHEN has_role(auth.uid(),'client') THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT t.id,t.name,c.hotel_name,t.status,t.blocked_since,t.escalation_level,t.blocker_reason,'launch' kind FROM client_tasks t JOIN clients c ON c.id=t.client_id LEFT JOIN pipelines p ON p.code=t.pipeline_code WHERE t.status IN('blocked','waiting_client') AND blocker_can_manage(t.client_id,p.id) AND NOT client_on_hold(t.client_id) AND NOT c.is_test AND NOT c.is_demo UNION ALL SELECT t.id,i.name,c.hotel_name,t.status,t.blocked_since,t.escalation_level,t.blocker_reason,'recurring' FROM recurring_tasks t JOIN activity_items i ON i.id=t.item_id JOIN activity_plans ap ON ap.id=t.plan_id JOIN client_pipelines cp ON cp.id=ap.client_pipeline_id JOIN clients c ON c.id=cp.client_id WHERE t.status IN('blocked','waiting_client') AND blocker_can_manage(cp.client_id,cp.pipeline_id) AND NOT client_on_hold(cp.client_id) AND NOT c.is_test AND NOT c.is_demo)x),'[]') END);END $$;
REVOKE ALL ON FUNCTION public.blocked_workspace() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.blocked_workspace() TO authenticated,service_role;
DO $$ DECLARE f text;BEGIN
SELECT pg_get_functiondef('public.escalate_overdue_tasks()'::regprocedure) INTO f;f:=replace(f,'AND x.days_late >= 1','AND t.status NOT IN (''blocked'',''waiting_client'') AND x.days_late >= 1');f:=replace(f,'RETURN n;','RETURN n + public.escalate_blocked_tasks();');EXECUTE f;
END $$;
CREATE OR REPLACE FUNCTION public.remind_client_approvals() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN queue_blocker_reminders();END $$;
CREATE OR REPLACE FUNCTION public.activation_follow_up_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF TG_OP='INSERT' THEN SELECT id INTO NEW.assigned_to FROM profiles WHERE email='shalini@alcorgetaways.com' AND status='active';NEW.follow_up_due:=working_day_after((NEW.created_at AT TIME ZONE 'Asia/Kolkata')::date);
ELSIF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to OR NEW.follow_up_due IS DISTINCT FROM OLD.follow_up_due THEN RAISE EXCEPTION 'Activation follow-up owner and deadline are system-managed'; END IF;
IF NEW.status='activated' AND (NEW.scope_confirmed_at IS NULL OR NEW.onboarding_completed_at IS NULL OR NEW.tasks_assigned_at IS NULL OR coalesce(btrim(NEW.scope_notes),'')='') THEN RAISE EXCEPTION 'Confirm scope, complete add-on onboarding and assign the pipeline tasks before marking activated'; END IF;RETURN NEW;END $$;
CREATE TRIGGER activation_follow_up_guard BEFORE INSERT OR UPDATE ON public.pipeline_activation_requests FOR EACH ROW EXECUTE FUNCTION public.activation_follow_up_guard();
CREATE OR REPLACE FUNCTION public.activation_email_copy() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO client_message_outbox(client_id,channel,to_address,kind,subject,body,held,activation_request_id) SELECT NEW.client_id,'email','mohnish@group2001.in','activation_request','New activation request: '||p.name,c.hotel_name||' requested '||p.name||'. Shalini follow-up due '||NEW.follow_up_due||'.',true,NEW.id FROM clients c,pipelines p WHERE c.id=NEW.client_id AND p.id=NEW.pipeline_id;IF NEW.assigned_to IS NOT NULL THEN INSERT INTO notifications(user_id,title,body,link,kind) VALUES(NEW.assigned_to,'Activation follow-up due',NEW.follow_up_due::text,'/activation-requests','pipeline_activation');END IF;RETURN NEW;END $$;
CREATE TRIGGER activation_email_copy AFTER INSERT ON public.pipeline_activation_requests FOR EACH ROW EXECUTE FUNCTION public.activation_email_copy();
REVOKE ALL ON FUNCTION public.activation_follow_up_guard(),public.activation_email_copy() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.complete_activation_followup(_id uuid,_scope text,_onboarded boolean,_assigned boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM activity_require_ready();IF NOT(is_manager(auth.uid()) OR has_role(auth.uid(),'bd_manager')) THEN RAISE EXCEPTION 'BD or management only';END IF;IF coalesce(btrim(_scope),'')='' THEN RAISE EXCEPTION 'Describe the confirmed add-on scope';END IF;UPDATE pipeline_activation_requests SET scope_notes=btrim(_scope),scope_confirmed_at=now(),onboarding_completed_at=CASE WHEN _onboarded THEN now() ELSE onboarding_completed_at END,tasks_assigned_at=CASE WHEN _assigned THEN now() ELSE tasks_assigned_at END,status=CASE WHEN _onboarded AND _assigned THEN 'activated' ELSE 'contacted' END WHERE id=_id;END $$;
REVOKE ALL ON FUNCTION public.complete_activation_followup(uuid,text,boolean,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.complete_activation_followup(uuid,text,boolean,boolean) TO authenticated,service_role;
DO $$ DECLARE f text;BEGIN
SELECT pg_get_functiondef('public.team_scorecard(date)'::regprocedure) INTO f;f:=replace(f,'(is_manager(auth.uid()) OR has_role(auth.uid(),''hr'') OR p.id = auth.uid())','scorecard_can_view(p.id)');EXECUTE f;
SELECT pg_get_functiondef('public.activity_person_summary(date)'::regprocedure) INTO f;f:=replace(f,'(is_manager(auth.uid()) OR has_role(auth.uid(),''hr'') OR t.owner_id=auth.uid())','scorecard_can_view(t.owner_id)');EXECUTE f;
SELECT pg_get_functiondef('public.department_scorecards(date)'::regprocedure) INTO f;f:=replace(f,'(is_manager(auth.uid()) OR has_role(auth.uid(),''hr'') OR is_pipeline_member(auth.uid(),pl.id))','scorecard_can_view(pm.user_id)');f:=replace(f,'WHERE pm.pipeline_id=p.id AND pm.active GROUP BY','WHERE pm.pipeline_id=p.id AND pm.active AND scorecard_can_view(pm.user_id) GROUP BY');EXECUTE f;
SELECT pg_get_functiondef('public.rd_grades(date,date)'::regprocedure) INTO f;f:=replace(f,'public.can_manage_rd(auth.uid()) OR public.has_role(auth.uid(), ''hr'')','public.is_staff(auth.uid()) OR public.has_role(auth.uid(), ''hr'')');f:=replace(f,'''revenue_total'', (s->>''revenue_booked'')::numeric','''revenue_total'', CASE WHEN public.can_view_commercials(auth.uid()) THEN (s->>''revenue_booked'')::numeric END');f:=replace(f,'LATERAL public._rd_stats(a.user_id, _from, _to) s);','LATERAL public._rd_stats(a.user_id, _from, _to) s WHERE public.scorecard_can_view(a.user_id));');EXECUTE f;
SELECT pg_get_functiondef('public.save_activity_plan(uuid,date,jsonb,uuid,boolean)'::regprocedure) INTO f;f:=replace(f,'bak:=nullif(r->>''backup_id'','''')::uuid','bak:=coalesce(nullif(r->>''backup_id'','''')::uuid,pipeline_default_backup(cp.pipeline_id))');EXECUTE f;
SELECT pg_get_functiondef('public.update_recurring_task(uuid,text,date,text,uuid,uuid)'::regprocedure) INTO f;f:=replace(f,'_status NOT IN(''not_started'',''in_progress'',''done'',''closed'')','_status NOT IN(''not_started'',''in_progress'',''blocked'',''waiting_client'',''done'',''closed'')');f:=replace(f,'IF _due IS NULL AND _status NOT IN','IF _status=''done'' AND t.stage=''approval'' AND EXISTS(SELECT 1 FROM task_approval_blockers b WHERE b.task_kind=''recurring'' AND b.task_id=t.id AND b.owner_approved_at IS NULL AND b.resolved_at IS NULL) THEN RAISE EXCEPTION ''The client must approve this item first''; END IF; IF _due IS NULL AND _status NOT IN');EXECUTE f;
SELECT pg_get_functiondef('public.activity_workspace(date,uuid,text,boolean)'::regprocedure) INTO f;f:=replace(f,'''owner_id'',t.owner_id,','''escalation_level'',t.escalation_level,''blocker_reason'',t.blocker_reason,''owner_id'',t.owner_id,');EXECUTE f;
END $$;